-- Name: check_objet_credit(); Type: FUNCTION; Schema: gpp_exhaustives; Owner: postgres
--

CREATE FUNCTION gpp_exhaustives.check_objet_credit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_eligible text;
BEGIN
    SELECT objet_credit_eligible
    INTO v_eligible
    FROM gpp_conventions.conventions
    WHERE id_gpp = NEW.id_gpp;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Convention introuvable pour id_gpp = %', NEW.id_gpp;
    END IF;

    IF NOT (
        string_to_array(v_eligible, ', ')::text[] @> ARRAY[NEW.objet_credit::text]
    ) THEN
        RAISE EXCEPTION 'objet_credit "%" non éligible pour % (éligibles : %)',
            NEW.objet_credit, NEW.id_gpp, v_eligible;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION gpp_exhaustives.check_objet_credit() OWNER TO postgres;

